          sourceType: "SUBSCRIPTION",
          sourceId: sub2.id,
          sourceKey: `COM-UPG:${sub2.id}:${effective}`,
          notes: `Subscription ${sub2.number} plan upgrade`,
          purpose: AccountingPurpose.SUBSCRIPTION_INVOICE,
          prefix: "INV"
