      title: `${s.register_code} Z#${s.z_number}: cash ${new Money(s.cash_difference).isNegative() ? "short" : "over"} ${new Money(s.cash_difference).abs().toFixed(2)}`,
      body: `Cashier ${s.cashier_name}. Review the variance notes and audit trail.`,
      entity_type: "POS_SESSION",
